26	/**
27	 * Convert raw the value in to inner value in List.
28	 *
29	 * [Performance sensitive]
30	 *
31	 * [Caution]: this is the key logic of user value parser.
32	 * For backward compatibility, do not modify it until you have to!
33	 */
34	export function parseDataValue(
35	    value: any,
36	    // For high performance, do not omit the second param.
37	    opt: {
38	        // Default type: 'number'. There is no 'unknown' type. That is, a string
39	        // will be parsed to NaN if do not set `type` as 'ordinal'. It has been
40	        // the logic in `List.ts` for long time. Follow the same way if you need
41	        // to get same result as List did from a raw value.
42	        type?: DimensionType
43	    }
44	): ParsedValue {
45	    // Performance sensitive.
46	    const dimType = opt && opt.type;
47	    if (dimType === 'ordinal') {
48	        // If given value is a category string
49	        return value;
50	    }
51	
52	    if (dimType === 'time'
53	        // spead up when using timestamp
54	        && !isNumber(value)
55	        && value != null
56	        && value !== '-'
57	    ) {
58	        value = +parseDate(value);
59	    }
60	
61	    // dimType defaults 'number'.
62	    // If dimType is not ordinal and value is null or undefined or NaN or '-',
63	    // parse to NaN.
64	    // number-like string (like ' 123 ') can be converted to a number.
65	    // where null/undefined or other string will be converted to NaN.
66	    return (value == null || value === '')
67	        ? NaN
68	        // If string (like '-'), using '+' parse to NaN
69	        // If object, also parse to NaN
70	        : +value;
71	};
