76	export type RawValueParserType = 'number' | 'time' | 'trim';
77	type RawValueParser = (val: unknown) => unknown;
78	const valueParserMap = createHashMap<RawValueParser, RawValueParserType>({
79	    'number': function (val): number {
80	        // Do not use `numericToNumber` here. We have `numericToNumber` by default.
81	        // Here the number parser can have loose rule:
82	        // enable to cut suffix: "120px" => 120, "14%" => 14.
83	        return parseFloat(val as string);
84	    },
85	    'time': function (val): number {
86	        // return timestamp.
87	        return +parseDate(val);
88	    },
89	    'trim': function (val) {
90	        return isString(val) ? trim(val) : val;
91	    }
92	});
