23	export default function ariaPreprocessor(option: ECUnitOption & AriaOptionMixin) {
24	    if (!option || !option.aria) {
25	        return;
26	    }
27	
28	    const aria = option.aria;
29	    // aria.show is deprecated and should use aria.enabled instead
30	    if ((aria as any).show != null) {
31	        aria.enabled = (aria as any).show;
32	    }
33	
34	    aria.label = aria.label || {};
35	    // move description, general, series, data to be under aria.label
36	    zrUtil.each(['description', 'general', 'series', 'data'], name => {
37	        if ((aria as any)[name] != null) {
38	            (aria.label as any)[name] = (aria as any)[name];
39	        }
40	    });
41	}

