296	function createBlurDefaultState(
297	    el: Displayable,
298	    stateName: 'blur',
299	    state: Displayable['states'][number]
300	): DisplayableState {
301	    const hasBlur = indexOf(el.currentStates, stateName) >= 0;
302	    const currentOpacity = el.style.opacity;
303	
304	    const fromState = !hasBlur
305	        ? getFromStateStyle(el, ['opacity'], stateName, {
306	            opacity: 1
307	        })
308	        : null;
309	
310	    state = state || {};
311	    let blurStyle = state.style || {};
312	    if (blurStyle.opacity == null) {
313	        // clone state
314	        state = extend({}, state);
315	        blurStyle = extend({
316	            // Already being applied 'emphasis'. DON'T mul opacity multiple times.
317	            opacity: hasBlur ? currentOpacity : (fromState.opacity * 0.1)
318	        }, blurStyle);
319	        state.style = blurStyle;
320	    }
321	
322	    return state;
323	}
