325	function elementStateProxy(this: Displayable, stateName: string, targetStates?: string[]): DisplayableState {
326	    const state = this.states[stateName];
327	    if (this.style) {
328	        if (stateName === 'emphasis') {
329	            return createEmphasisDefaultState(this, stateName, targetStates, state);
330	        }
331	        else if (stateName === 'blur') {
332	            return createBlurDefaultState(this, stateName, state);
333	        }
334	        else if (stateName === 'select') {
335	            return createSelectDefaultState(this, stateName, state);
336	        }
337	    }
338	    return state;
339	}
