402	export function allLeaveBlur(api: ExtensionAPI) {
403	    const model = api.getModel();
404	    const leaveBlurredSeries: SeriesModel[] = [];
405	    const allComponentViews: ComponentView[] = [];
406	    model.eachComponent(function (componentType, componentModel) {
407	        const componentStates = getComponentStates(componentModel);
408	        const isSeries = componentType === 'series';
409	        const view = isSeries ? api.getViewOfSeriesModel(componentModel as SeriesModel)
410	            : api.getViewOfComponentModel(componentModel);
411	        !isSeries && allComponentViews.push(view as ComponentView);
412	        if (componentStates.isBlured) {
413	            // Leave blur anyway
414	            view.group.traverse(function (child) {
415	                singleLeaveBlur(child);
416	            });
417	            isSeries && leaveBlurredSeries.push(componentModel as SeriesModel);
418	        }
419	        componentStates.isBlured = false;
420	    });
421	    each(allComponentViews, function (view) {
422	        if (view && view.toggleBlurSeries) {
423	            view.toggleBlurSeries(leaveBlurredSeries, false, model);
424	        }
425	    });
426	}
