544	export function blurSeriesFromHighlightPayload(
545	    seriesModel: SeriesModel,
546	    payload: HighlightPayload,
547	    api: ExtensionAPI
548	) {
549	    const seriesIndex = seriesModel.seriesIndex;
550	    const data = seriesModel.getData(payload.dataType);
551	    if (!data) {
552	        if (__DEV__) {
553	            error(`Unknown dataType ${payload.dataType}`);
554	        }
555	        return;
556	    }
557	    let dataIndex = queryDataIndex(data, payload);
558	    // Pick the first one if there is multiple/none exists.
559	    dataIndex = (isArray(dataIndex) ? dataIndex[0] : dataIndex) || 0;
560	    let el = data.getItemGraphicEl(dataIndex as number);
561	    if (!el) {
562	        const count = data.count();
563	        let current = 0;
564	        // If data on dataIndex is NaN.
565	        while (!el && current < count) {
566	            el = data.getItemGraphicEl(current++);
567	        }
568	    }
569	
570	    if (el) {
571	        const ecData = getECData(el);
572	        blurSeries(
573	            seriesIndex, ecData.focus, ecData.blurScope, api
574	        );
575	    }
576	    else {
577	        // If there is no element put on the data. Try getting it from raw option
578	        // TODO Should put it on seriesModel?
579	        const focus = seriesModel.get(['emphasis', 'focus']);
580	        const blurScope = seriesModel.get(['emphasis', 'blurScope']);
581	        if (focus != null) {
582	            blurSeries(seriesIndex, focus, blurScope, api);
583	        }
584	    }
585	}
