587	export function findComponentHighDownDispatchers(
588	    componentMainType: ComponentMainType,
589	    componentIndex: number,
590	    name: string,
591	    api: ExtensionAPI
592	): {
593	    focusSelf: boolean;
594	    // If return null/undefined, do not support this feature.
595	    dispatchers: Element[];
596	} {
597	    const ret = {
598	        focusSelf: false,
599	        dispatchers: null as Element[]
600	    };
601	    if (componentMainType == null
602	        || componentMainType === 'series'
603	        || componentIndex == null
604	        || name == null
605	    ) {
606	        return ret;
607	    }
608	
609	    const componentModel = api.getModel().getComponent(componentMainType, componentIndex);
610	    if (!componentModel) {
611	        return ret;
612	    }
613	
614	    const view = api.getViewOfComponentModel(componentModel);
615	    if (!view || !view.findHighDownDispatchers) {
616	        return ret;
617	    }
618	
619	    const dispatchers = view.findHighDownDispatchers(name);
620	
621	    // At presnet, the component (like Geo) only blur inside itself.
622	    // So we do not use `blurScope` in component.
623	    let focusSelf: boolean;
624	    for (let i = 0; i < dispatchers.length; i++) {
625	        if (__DEV__ && !isHighDownDispatcher(dispatchers[i])) {
626	            error('param should be highDownDispatcher');
627	        }
628	        if (getECData(dispatchers[i]).focus === 'self') {
629	            focusSelf = true;
630	            break;
631	        }
632	    }
633	
634	    return { focusSelf, dispatchers };
635	}
