637	export function handleGlobalMouseOverForHighDown(
638	    dispatcher: Element,
639	    e: ElementEvent,
640	    api: ExtensionAPI
641	): void {
642	    if (__DEV__ && !isHighDownDispatcher(dispatcher)) {
643	        error('param should be highDownDispatcher');
644	    }
645	
646	    const ecData = getECData(dispatcher);
647	
648	    const { dispatchers, focusSelf } = findComponentHighDownDispatchers(
649	        ecData.componentMainType, ecData.componentIndex, ecData.componentHighDownName, api
650	    );
651	    // If `findHighDownDispatchers` is supported on the component,
652	    // highlight/downplay elements with the same name.
653	    if (dispatchers) {
654	        if (focusSelf) {
655	            blurComponent(ecData.componentMainType, ecData.componentIndex, api);
656	        }
657	        each(dispatchers, dispatcher => enterEmphasisWhenMouseOver(dispatcher, e));
658	    }
659	    else {
660	        // Try blur all in the related series. Then emphasis the hoverred.
661	        // TODO. progressive mode.
662	        blurSeries(ecData.seriesIndex, ecData.focus, ecData.blurScope, api);
663	        if (ecData.focus === 'self') {
664	            blurComponent(ecData.componentMainType, ecData.componentIndex, api);
665	        }
666	        // Other than series, component that not support `findHighDownDispatcher` will
667	        // also use it. But in this case, highlight/downplay are only supported in
668	        // mouse hover but not in dispatchAction.
669	        enterEmphasisWhenMouseOver(dispatcher, e);
670	    }
671	}
