812	    for (let i = 0; i < OTHER_STATES.length; i++) {
813	        const stateName = OTHER_STATES[i];
814	        const model = itemModel.getModel([stateName, styleType]);
815	        const state = el.ensureState(stateName);
816	        // Let it throw error if getterType is not found.
817	        state.style = getter ? getter(model) : model[defaultStyleGetterMap[styleType]]();
818	    }
819	}
