822	/**
823	 *
824	 * Set element as highlight / downplay dispatcher.
825	 * It will be checked when element received mouseover event or from highlight action.
826	 * It's in change of all highlight/downplay behavior of it's children.
827	 *
828	 * @param el
829	 * @param el.highDownSilentOnTouch
830	 *        In touch device, mouseover event will be trigger on touchstart event
831	 *        (see module:zrender/dom/HandlerProxy). By this mechanism, we can
832	 *        conveniently use hoverStyle when tap on touch screen without additional
833	 *        code for compatibility.
834	 *        But if the chart/component has select feature, which usually also use
835	 *        hoverStyle, there might be conflict between 'select-highlight' and
836	 *        'hover-highlight' especially when roam is enabled (see geo for example).
837	 *        In this case, `highDownSilentOnTouch` should be used to disable
838	 *        hover-highlight on touch device.
839	 * @param asDispatcher If `false`, do not set as "highDownDispatcher".
840	 */
841	export function setAsHighDownDispatcher(el: Element, asDispatcher: boolean) {
842	    const disable = asDispatcher === false;
843	    const extendedEl = el as ExtendedElement;
844	    // Make `highDownSilentOnTouch` and `onStateChange` only work after
845	    // `setAsHighDownDispatcher` called. Avoid it is modified by user unexpectedly.
846	    if ((el as ECElement).highDownSilentOnTouch) {
847	        extendedEl.__highDownSilentOnTouch = (el as ECElement).highDownSilentOnTouch;
848	    }
849	    // Simple optimize, since this method might be
850	    // called for each elements of a group in some cases.
851	    if (!disable || extendedEl.__highDownDispatcher) {
852	        // Emphasis, normal can be triggered manually by API or other components like hover link.
853	        // el[method]('emphasis', onElementEmphasisEvent)[method]('normal', onElementNormalEvent);
854	        // Also keep previous record.
855	        extendedEl.__highByOuter = extendedEl.__highByOuter || 0;
856	        extendedEl.__highDownDispatcher = !disable;
857	    }
858	}
859	
860	export function isHighDownDispatcher(el: Element): boolean {
861	    return !!(el && (el as ExtendedDisplayable).__highDownDispatcher);
862	}
863	
864	/**
865	 * Enable component highlight/downplay features:
866	 * + hover link (within the same name)
867	 * + focus blur in component
868	 */
869	export function enableComponentHighDownFeatures(
870	    el: Element,
871	    componentModel: ComponentModel,
872	    componentHighDownName: string
873	): void {
874	    const ecData = getECData(el);
875	    ecData.componentMainType = componentModel.mainType;
876	    ecData.componentIndex = componentModel.componentIndex;
877	    ecData.componentHighDownName = componentHighDownName;
878	}
