880	/**
881	 * Support highlight/downplay record on each elements.
882	 * For the case: hover highlight/downplay (legend, visualMap, ...) and
883	 * user triggered highlight/downplay should not conflict.
884	 * Only all of the highlightDigit cleared, return to normal.
885	 * @param {string} highlightKey
886	 * @return {number} highlightDigit
887	 */
888	export function getHighlightDigit(highlightKey: number) {
889	    let highlightDigit = _highlightKeyMap[highlightKey];
890	    if (highlightDigit == null && _highlightNextDigit <= 32) {
891	        highlightDigit = _highlightKeyMap[highlightKey] = _highlightNextDigit++;
892	    }
893	    return highlightDigit;
894	}
895	
896	export function isSelectChangePayload(payload: Payload) {
897	    const payloadType = payload.type;
898	    return payloadType === SELECT_ACTION_TYPE
899	        || payloadType === UNSELECT_ACTION_TYPE
900	        || payloadType === TOGGLE_SELECT_ACTION_TYPE;
901	}
902	
903	export function isHighDownPayload(payload: Payload): payload is HighlightPayload | DownplayPayload {
904	    const payloadType = payload.type;
905	    return payloadType === HIGHLIGHT_ACTION_TYPE
906	        || payloadType === DOWNPLAY_ACTION_TYPE;
907	}
