909	export function savePathStates(el: Path) {
910	    const store = getSavedStates(el);
911	    store.normalFill = el.style.fill;
912	    store.normalStroke = el.style.stroke;
913	
914	    const selectState = el.states.select || {};
915	    store.selectFill = (selectState.style && selectState.style.fill) || null;
916	    store.selectStroke = (selectState.style && selectState.style.stroke) || null;
917	}

