1114	    buildPath(ctx: CanvasRenderingContext2D, shape: LagePathShape) {
1115	        // Drawing lines is more efficient than drawing
1116	        // a whole line or drawing rects.
1117	        const points = shape.points;
1118	        const baseDimIdx = this.baseDimIdx;
1119	        const valueDimIdx = 1 - this.baseDimIdx;
1120	        const startPoint = [];
1121	        const size = [];
1122	        const barWidth = this.barWidth;
1123	
1124	        for (let i = 0; i < points.length; i += 3) {
1125	            size[baseDimIdx] = barWidth;
1126	            size[valueDimIdx] = points[i + 2];
1127	            startPoint[baseDimIdx] = points[i + baseDimIdx];
1128	            startPoint[valueDimIdx] = points[i + valueDimIdx];
1129	            ctx.rect(startPoint[0], startPoint[1], size[0], size[1]);
1130	        }
1131	    }
