1134	function createLarge(
1135	    seriesModel: BarSeriesModel,
1136	    group: Group,
1137	    progressiveEls?: Element[],
1138	    incremental?: boolean
1139	) {
1140	    // TODO support polar
1141	    const data = seriesModel.getData();
1142	    const baseDimIdx = data.getLayout('valueAxisHorizontal') ? 1 : 0;
1143	
1144	    const largeDataIndices = data.getLayout('largeDataIndices');
1145	    const barWidth = data.getLayout('size');
1146	
1147	    const backgroundModel = seriesModel.getModel('backgroundStyle');
1148	    const bgPoints = data.getLayout('largeBackgroundPoints');
1149	
1150	    if (bgPoints) {
1151	        const bgEl = new LargePath({
1152	            shape: {
1153	                points: bgPoints
1154	            },
1155	            incremental: !!incremental,
1156	            silent: true,
1157	            z2: 0
1158	        });
1159	        bgEl.baseDimIdx = baseDimIdx;
1160	        bgEl.largeDataIndices = largeDataIndices;
1161	        bgEl.barWidth = barWidth;
1162	        bgEl.useStyle(backgroundModel.getItemStyle());
1163	        group.add(bgEl);
1164	
1165	        progressiveEls && progressiveEls.push(bgEl);
1166	    }
1167	
1168	    const el = new LargePath({
1169	        shape: {points: data.getLayout('largePoints')},
1170	        incremental: !!incremental,
1171	        ignoreCoarsePointer: true,
1172	        z2: 1
1173	    });
1174	    el.baseDimIdx = baseDimIdx;
1175	    el.largeDataIndices = largeDataIndices;
1176	    el.barWidth = barWidth;
