679	interface Clipper {
680	    (coordSysBoundingRect: PolarCoordArea | CartesianCoordArea, layout: RectLayout | SectorLayout): boolean
681	}
682	const clip: {
683	    [key in 'cartesian2d' | 'polar']: Clipper
684	} = {
685	    cartesian2d(coordSysBoundingRect: CartesianCoordArea, layout: Rect['shape']) {
686	        const signWidth = layout.width < 0 ? -1 : 1;
687	        const signHeight = layout.height < 0 ? -1 : 1;
688	        // Needs positive width and height
689	        if (signWidth < 0) {
690	            layout.x += layout.width;
691	            layout.width = -layout.width;
692	        }
693	        if (signHeight < 0) {
694	            layout.y += layout.height;
695	            layout.height = -layout.height;
696	        }
697	
698	        const coordSysX2 = coordSysBoundingRect.x + coordSysBoundingRect.width;
699	        const coordSysY2 = coordSysBoundingRect.y + coordSysBoundingRect.height;
700	        const x = mathMax(layout.x, coordSysBoundingRect.x);
701	        const x2 = mathMin(layout.x + layout.width, coordSysX2);
702	        const y = mathMax(layout.y, coordSysBoundingRect.y);
703	        const y2 = mathMin(layout.y + layout.height, coordSysY2);
704	
705	        const xClipped = x2 < x;
706	        const yClipped = y2 < y;
707	
708	        // When xClipped or yClipped, the element will be marked as `ignore`.
709	        // But we should also place the element at the edge of the coord sys bounding rect.
710	        // Because if data changed and the bar shows again, its transition animation
711	        // will begin at this place.
712	        layout.x = (xClipped && x > coordSysX2) ? x2 : x;
713	        layout.y = (yClipped && y > coordSysY2) ? y2 : y;
714	        layout.width = xClipped ? 0 : x2 - x;
715	        layout.height = yClipped ? 0 : y2 - y;
716	
717	        // Reverse back
718	        if (signWidth < 0) {
719	            layout.x += layout.width;
720	            layout.width = -layout.width;
721	        }
722	        if (signHeight < 0) {
723	            layout.y += layout.height;
724	            layout.height = -layout.height;
725	        }
726	
727	        return xClipped || yClipped;
728	    },
729	
730	    polar(coordSysClipArea: PolarCoordArea, layout: Sector['shape']) {
731	        const signR = layout.r0 <= layout.r ? 1 : -1;
732	        // Make sure r is larger than r0
733	        if (signR < 0) {
734	            const tmp = layout.r;
735	            layout.r = layout.r0;
736	            layout.r0 = tmp;
737	        }
738	
739	        const r = mathMin(layout.r, coordSysClipArea.r);
740	        const r0 = mathMax(layout.r0, coordSysClipArea.r0);
741	
742	        layout.r = r;
743	        layout.r0 = r0;
744	
745	        const clipped = r - r0 < 0;
746	
747	        // Reverse back
748	        if (signR < 0) {
749	            const tmp = layout.r;
750	            layout.r = layout.r0;
751	            layout.r0 = tmp;
752	        }
753	
754	        return clipped;
755	    }
756	};
