29	        this._createPolyline(lineData, idx, seriesScope);
30	    }
31	
32	    private _createPolyline(lineData: SeriesData, idx: number, seriesScope: LineDrawSeriesScope) {
33	        // let seriesModel = lineData.hostModel;
34	        const points = lineData.getItemLayout(idx);
35	
36	        const line = new graphic.Polyline({
37	            shape: {
38	                points: points
39	            }
