41	
42	        this.add(line);
43	
44	        this._updateCommonStl(lineData, idx, seriesScope);
45	    };
46	
47	    updateData(lineData: SeriesData, idx: number, seriesScope: LineDrawSeriesScope) {
48	        const seriesModel = lineData.hostModel;
49	
50	        const line = this.childAt(0) as graphic.Polyline;
