68	        let blurScope = (seriesScope && seriesScope.blurScope) as BlurScope;
69	        let emphasisDisabled = seriesScope && seriesScope.emphasisDisabled;
70	
71	
72	        if (!seriesScope || lineData.hasItemOption) {
73	            const emphasisModel = itemModel.getModel('emphasis');
74	            emphasisLineStyle = emphasisModel.getModel('lineStyle').getLineStyle();
75	            emphasisDisabled = emphasisModel.get('disabled');
76	            focus = emphasisModel.get('focus');
77	            blurScope = emphasisModel.get('blurScope');
78	        }
