667	    /**
668	     * @public
669	     * @param {number} x Global coord x.
670	     * @param {number} y Global coord y.
671	     * @return {Object} info If not found, return undefined;
672	     * @return {number} info.node Target node.
673	     * @return {number} info.offsetX x refer to target node.
674	     * @return {number} info.offsetY y refer to target node.
675	     */
676	    findTarget(x: number, y: number): FoundTargetInfo {
677	        let targetInfo;
678	        const viewRoot = this.seriesModel.getViewRoot();
679	
680	        viewRoot.eachNode({attr: 'viewChildren', order: 'preorder'}, function (node) {
681	            const bgEl = this._storage.background[node.getRawIndex()];
682	            // If invisible, there might be no element.
683	            if (bgEl) {
684	                const point = bgEl.transformCoordToLocal(x, y);
685	                const shape = bgEl.shape;
686	
687	                // For performance consideration, don't use 'getBoundingRect'.
688	                if (shape.x <= point[0]
689	                    && point[0] <= shape.x + shape.width
690	                    && shape.y <= point[1]
691	                    && point[1] <= shape.y + shape.height
692	                ) {
693	                    targetInfo = {
694	                        node: node,
695	                        offsetX: point[0],
696	                        offsetY: point[1]
697	                    };
698	                }
699	                else {
700	                    return false; // Suppress visit subtree.
701	                }
702	            }
703	        }, this);
704	
705	        return targetInfo;
706	    }
707	}
