20	import * as graphic from '../../util/graphic';
21	import {round} from '../../util/number';
22	import SeriesModel from '../../model/Series';
23	import { SeriesOption } from '../../util/types';
24	import type Cartesian2D from '../../coord/cartesian/Cartesian2D';
