29	type SeriesModelWithLineWidth = SeriesModel<SeriesOption & {
30	    lineStyle?: { width?: number }
31	}>;
32	function createGridClipPath(
33	    cartesian: Cartesian2D,
34	    hasAnimation: boolean,
35	    seriesModel: SeriesModelWithLineWidth,
36	    done?: () => void,
37	    during?: (percent: number, clipRect: graphic.Rect) => void
38	) {
39	    const rect = cartesian.getArea();
40	
41	    let x = rect.x;
42	    let y = rect.y;
43	    let width = rect.width;
44	    let height = rect.height;
45	
46	    const lineWidth = seriesModel.get(['lineStyle', 'width']) || 2;
47	    // Expand the clip path a bit to avoid the border is clipped and looks thinner
48	    x -= lineWidth / 2;
49	    y -= lineWidth / 2;
50	    width += lineWidth;
51	    height += lineWidth;
52	
53	    // fix: https://github.com/apache/incubator-echarts/issues/11369
54	    width = Math.ceil(width);
55	    if (x !== Math.floor(x)) {
56	        x = Math.floor(x);
57	        // if no extra 1px on `width`, it will still be clipped since `x` is floored
58	        width++;
59	    }
60	
61	    const clipPath = new graphic.Rect({
62	        shape: {
63	            x: x,
64	            y: y,
65	            width: width,
66	            height: height
67	        }
68	    });
69	
70	    if (hasAnimation) {
71	        const baseAxis = cartesian.getBaseAxis();
72	        const isHorizontal = baseAxis.isHorizontal();
73	        const isAxisInversed = baseAxis.inverse;
74	
75	        if (isHorizontal) {
76	            if (isAxisInversed) {
77	                clipPath.shape.x += width;
78	            }
79	            clipPath.shape.width = 0;
80	        }
81	        else {
82	            if (!isAxisInversed) {
83	                clipPath.shape.y += height;
84	            }
85	            clipPath.shape.height = 0;
86	        }
87	
88	        const duringCb = isFunction(during)
89	            ? (percent: number) => {
90	                during(percent, clipPath);
91	            }
92	            : null;
93	
94	        graphic.initProps(clipPath, {
95	            shape: {
96	                width: width,
97	                height: height,
98	                x: x,
99	                y: y
100	            }
101	        }, seriesModel, null, done, duringCb);
102	    }
103	
104	    return clipPath;
105	}
