107	function createPolarClipPath(
108	    polar: Polar,
109	    hasAnimation: boolean,
110	    seriesModel: SeriesModelWithLineWidth
111	) {
112	    const sectorArea = polar.getArea();
113	    // Avoid float number rounding error for symbol on the edge of axis extent.
114	
115	    const r0 = round(sectorArea.r0, 1);
116	    const r = round(sectorArea.r, 1);
117	    const clipPath = new graphic.Sector({
118	        shape: {
119	            cx: round(polar.cx, 1),
120	            cy: round(polar.cy, 1),
121	            r0: r0,
122	            r: r,
123	            startAngle: sectorArea.startAngle,
124	            endAngle: sectorArea.endAngle,
125	            clockwise: sectorArea.clockwise
126	        }
127	    });
128	
129	    if (hasAnimation) {
130	        const isRadial = polar.getBaseAxis().dim === 'angle';
131	
132	        if (isRadial) {
133	            clipPath.shape.endAngle = sectorArea.startAngle;
134	        }
135	        else {
136	            clipPath.shape.r = r0;
137	        }
138	
139	        graphic.initProps(clipPath, {
140	            shape: {
141	                endAngle: sectorArea.endAngle,
142	                r: r
143	            }
144	        }, seriesModel);
145	    }
146	    return clipPath;
147	}
148	
149	function createClipPath(
150	    coordSys: CoordinateSystem,
151	    hasAnimation: boolean,
152	    seriesModel: SeriesModelWithLineWidth,
153	    done?: () => void,
154	    during?: (percent: number) => void
155	) {
156	    if (!coordSys) {
157	        return null;
158	    }
159	    else if (coordSys.type === 'polar') {
160	        return createPolarClipPath(coordSys as Polar, hasAnimation, seriesModel);
161	    }
162	    else if (coordSys.type === 'cartesian2d') {
163	        return createGridClipPath(coordSys as Cartesian2D, hasAnimation, seriesModel, done, during);
164	    }
165	    return null;
166	}
