248	interface TooltipContentOption {
249	    /**
250	     * Specify target container of the tooltip element.
251	     * Can either be an HTMLElement, CSS selector string, or a function that returns an HTMLElement.
252	     */
253	    appendTo: ((chartContainer: HTMLElement) => HTMLElement | undefined | null) | HTMLElement | string
254	}
255	
256	class TooltipHTMLContent {
257	
258	    el: HTMLDivElement;
259	
260	    private _api: ExtensionAPI;
261	    private _container: HTMLElement | undefined | null;
262	
263	    private _show: boolean = false;
264	
265	    private _styleCoord: [number, number, number, number] = [0, 0, 0, 0];
266	
267	    private _enterable = true;
268	    private _zr: ZRenderType;
269	
270	    private _alwaysShowContent: boolean = false;
271	    private _hideTimeout: number;
272	    /**
273	     * Hide delay time
274	     */
275	    private _hideDelay: number;
276	
277	    private _inContent: boolean;
278	    private _firstShow = true;
279	    private _longHide = true;
280	    /**
281	     * Record long-time hide
282	     */
283	    private _longHideTimeout: number;
284	
285	    constructor(
286	        api: ExtensionAPI,
287	        opt: TooltipContentOption
288	    ) {
289	        if (env.wxa) {
290	            return null;
291	        }
292	
293	        const el = document.createElement('div');
294	        // TODO: TYPE
295	        (el as any).domBelongToZr = true;
296	        this.el = el;
297	        const zr = this._zr = api.getZr();
298	
299	        const appendTo = opt.appendTo;
300	        const container: HTMLElement | null | undefined = appendTo && (
301	            isString(appendTo)
302	                ? document.querySelector(appendTo)
303	                : isDom(appendTo)
304	                    ? appendTo
305	                    : isFunction(appendTo) && appendTo(api.getDom())
306	        );
307	
308	        makeStyleCoord(this._styleCoord, zr, container, api.getWidth() / 2, api.getHeight() / 2);
309	
310	        (container || api.getDom()).appendChild(el);
311	
312	        this._api = api;
313	        this._container = container;
314	
315	        // FIXME
316	        // Is it needed to trigger zr event manually if
317	        // the browser do not support `pointer-events: none`.
318	
319	        const self = this;
320	        el.onmouseenter = function () {
321	            // clear the timeout in hideLater and keep showing tooltip
322	            if (self._enterable) {
323	                clearTimeout(self._hideTimeout);
324	                self._show = true;
325	            }
326	            self._inContent = true;
327	        };
328	        el.onmousemove = function (e) {
329	            e = e || (window as any).event;
330	            if (!self._enterable) {
331	                // `pointer-events: none` is set to tooltip content div
332	                // if `enterable` is set as `false`, and `el.onmousemove`
333	                // can not be triggered. But in browser that do not
334	                // support `pointer-events`, we need to do this:
335	                // Try trigger zrender event to avoid mouse
336	                // in and out shape too frequently
337	                const handler = zr.handler;
338	                const zrViewportRoot = zr.painter.getViewportRoot();
339	                normalizeEvent(zrViewportRoot, e as ZRRawEvent, true);
340	                handler.dispatch('mousemove', e);
341	            }
342	        };
343	        el.onmouseleave = function () {
344	            // set `_inContent` to `false` before `hideLater`
345	            self._inContent = false;
346	
347	            if (self._enterable) {
348	                if (self._show) {
349	                    self.hideLater(self._hideDelay);
350	                }
351	            }
352	        };
353	    }
354	
355	    /**
356	     * Update when tooltip is rendered
357	     */
358	    update(tooltipModel: Model<TooltipOption>) {
359	        // FIXME
360	        // Move this logic to ec main?
361	        if (!this._container) {
362	            const container = this._api.getDom();
363	            const position = getComputedStyle(container, 'position');
364	            const domStyle = container.style;
365	            if (domStyle.position !== 'absolute' && position !== 'absolute') {
366	                domStyle.position = 'relative';
367	            }
368	        }
369	
370	        // move tooltip if chart resized
371	        const alwaysShowContent = tooltipModel.get('alwaysShowContent');
372	        alwaysShowContent && this._moveIfResized();
373	
374	        // update alwaysShowContent
375	        this._alwaysShowContent = alwaysShowContent;
376	
377	        // update className
378	        this.el.className = tooltipModel.get('className') || '';
379	
380	        // Hide the tooltip
381	        // PENDING
382	        // this.hide();
383	    }
384	
385	    show(tooltipModel: Model<TooltipOption>, nearPointColor: ZRColor) {
386	        clearTimeout(this._hideTimeout);
387	        clearTimeout(this._longHideTimeout);
388	        const el = this.el;
389	        const style = el.style;
390	        const styleCoord = this._styleCoord;
391	        if (!el.innerHTML) {
392	            style.display = 'none';
393	        }
394	        else {
395	            style.cssText = gCssText
396	                + assembleCssText(tooltipModel, !this._firstShow, this._longHide)
397	                // initial transform
398	                + assembleTransform(styleCoord[0], styleCoord[1], true)
399	                + `border-color:${convertToColorString(nearPointColor)};`
400	                + (tooltipModel.get('extraCssText') || '')
401	                // If mouse occasionally move over the tooltip, a mouseout event will be
402	                // triggered by canvas, and cause some unexpectable result like dragging
403	                // stop, "unfocusAdjacency". Here `pointer-events: none` is used to solve
404	                // it. Although it is not supported by IE8~IE10, fortunately it is a rare
405	                // scenario.
406	                + `;pointer-events:${this._enterable ? 'auto' : 'none'}`;
407	        }
408	
409	        this._show = true;
410	        this._firstShow = false;
411	        this._longHide = false;
412	    }
413	
414	    setContent(
415	        content: string | HTMLElement | HTMLElement[],
416	        markers: unknown,
417	        tooltipModel: Model<TooltipOption>,
418	        borderColor?: ZRColor,
419	        arrowPosition?: TooltipOption['position']
420	    ) {
421	        const el = this.el;
422	
423	        if (content == null) {
424	            el.innerHTML = '';
425	            return;
426	        }
427	
428	        let arrow = '';
429	        if (isString(arrowPosition) && tooltipModel.get('trigger') === 'item'
430	            && !shouldTooltipConfine(tooltipModel)) {
431	            arrow = assembleArrow(tooltipModel, borderColor, arrowPosition);
432	        }
433	        if (isString(content)) {
434	            el.innerHTML = content + arrow;
435	        }
436	        else if (content) {
437	            // Clear previous
438	            el.innerHTML = '';
439	            if (!isArray(content)) {
440	                content = [content];
441	            }
442	            for (let i = 0; i < content.length; i++) {
443	                if (isDom(content[i]) && content[i].parentNode !== el) {
444	                    el.appendChild(content[i]);
445	                }
446	            }
447	            // no arrow if empty
448	            if (arrow && el.childNodes.length) {
449	                // no need to create a new parent element, but it's not supported by IE 10 and older.
450	                // const arrowEl = document.createRange().createContextualFragment(arrow);
451	                const arrowEl = document.createElement('div');
452	                arrowEl.innerHTML = arrow;
453	                el.appendChild(arrowEl);
454	            }
455	        }
456	    }
457	
458	    setEnterable(enterable: boolean) {
459	        this._enterable = enterable;
460	    }
461	
462	    getSize() {
463	        const el = this.el;
464	        return [el.offsetWidth, el.offsetHeight];
465	    }
466	
467	    moveTo(zrX: number, zrY: number) {
468	        const styleCoord = this._styleCoord;
469	        makeStyleCoord(styleCoord, this._zr, this._container, zrX, zrY);
470	
471	        if (styleCoord[0] != null && styleCoord[1] != null) {
472	            const style = this.el.style;
473	            const transforms = assembleTransform(styleCoord[0], styleCoord[1]) as string[][];
474	            each(transforms, (transform) => {
475	              style[transform[0] as any] = transform[1];
476	            });
477	        }
478	    }
479	
480	    /**
481	     * when `alwaysShowContent` is true,
482	     * move the tooltip after chart resized
483	     */
484	    _moveIfResized() {
485	        // The ratio of left to width
486	        const ratioX = this._styleCoord[2];
487	        // The ratio of top to height
488	        const ratioY = this._styleCoord[3];
489	        this.moveTo(
490	            ratioX * this._zr.getWidth(),
491	            ratioY * this._zr.getHeight()
492	        );
493	    }
494	
495	    hide() {
496	        const style = this.el.style;
497	        style.visibility = 'hidden';
498	        style.opacity = '0';
499	        env.transform3dSupported && (style.willChange = '');
500	        this._show = false;
501	        this._longHideTimeout = setTimeout(() => this._longHide = true, 500) as any;
502	    }
503	
504	    hideLater(time?: number) {
505	        if (this._show && !(this._inContent && this._enterable) && !this._alwaysShowContent) {
506	            if (time) {
507	                this._hideDelay = time;
508	                // Set show false to avoid invoke hideLater multiple times
509	                this._show = false;
510	                this._hideTimeout = setTimeout(bind(this.hide, this), time) as any;
511	            }
512	            else {
513	                this.hide();
514	            }
515	        }
516	    }
517	
518	    isShow() {
519	        return this._show;
520	    }
521	
522	    dispose() {
523	        clearTimeout(this._hideTimeout);
524	        clearTimeout(this._longHideTimeout);
525	
526	        const parentNode = this.el.parentNode;
527	        parentNode && parentNode.removeChild(this.el);
528	        this.el = this._container = null;
529	    }
530	
531	}
532	
533	export default TooltipHTMLContent;

