20	import * as zrUtil from 'zrender/src/core/util';
21	import VisualMapView from './VisualMapView';
22	import * as graphic from '../../util/graphic';
23	import {createSymbol} from '../../util/symbol';
24	import * as layout from '../../util/layout';
25	import * as helper from './helper';
26	import PiecewiseModel from './PiecewiseModel';
27	import { TextAlign } from 'zrender/src/core/types';
28	import { VisualMappingOption } from '../../visual/VisualMapping';
29	import { createTextStyle } from '../../label/labelStyle';
30	
31	class PiecewiseVisualMapView extends VisualMapView {
32	
33	    static type = 'visualMap.piecewise' as const;
34	
35	    type = PiecewiseVisualMapView.type;
36	
37	    visualMapModel: PiecewiseModel;
38	
39	    protected doRender() {
40	        const thisGroup = this.group;
41	
42	        thisGroup.removeAll();
43	
44	        const visualMapModel = this.visualMapModel;
45	        const textGap = visualMapModel.get('textGap');
46	        const textStyleModel = visualMapModel.textStyleModel;
47	        const textFont = textStyleModel.getFont();
48	        const textFill = textStyleModel.getTextColor();
49	        const itemAlign = this._getItemAlign();
50	        const itemSize = visualMapModel.itemSize;
51	        const viewData = this._getViewData();
52	        const endsText = viewData.endsText;
53	        const showLabel = zrUtil.retrieve(visualMapModel.get('showLabel', true), !endsText);
54	
55	        endsText && this._renderEndsText(
56	            thisGroup, endsText[0], itemSize, showLabel, itemAlign
57	        );
58	
59	        zrUtil.each(viewData.viewPieceList, function (item: typeof viewData.viewPieceList[number]) {
60	            const piece = item.piece;
61	
62	            const itemGroup = new graphic.Group();
63	            itemGroup.onclick = zrUtil.bind(this._onItemClick, this, piece);
64	
65	            this._enableHoverLink(itemGroup, item.indexInModelPieceList);
66	
67	            // TODO Category
68	            const representValue = visualMapModel.getRepresentValue(piece) as number;
69	
70	            this._createItemSymbol(
71	                itemGroup, representValue, [0, 0, itemSize[0], itemSize[1]]
72	            );
73	
74	            if (showLabel) {
75	                const visualState = this.visualMapModel.getValueState(representValue);
76	
77	                itemGroup.add(new graphic.Text({
78	                    style: {
79	                        x: itemAlign === 'right' ? -textGap : itemSize[0] + textGap,
80	                        y: itemSize[1] / 2,
81	                        text: piece.text,
82	                        verticalAlign: 'middle',
83	                        align: itemAlign as TextAlign,
84	                        font: textFont,
85	                        fill: textFill,
86	                        opacity: visualState === 'outOfRange' ? 0.5 : 1
87	                    }
88	                }));
89	            }
90	
91	            thisGroup.add(itemGroup);
92	        }, this);
93	
94	        endsText && this._renderEndsText(
95	            thisGroup, endsText[1], itemSize, showLabel, itemAlign
96	        );
97	
98	        layout.box(
99	            visualMapModel.get('orient'), thisGroup, visualMapModel.get('itemGap')
100	        );
101	
102	        this.renderBackground(thisGroup);
103	
104	        this.positionGroup(thisGroup);
105	    }
106	
107	    private _enableHoverLink(itemGroup: graphic.Group, pieceIndex: number) {
108	        itemGroup
109	            .on('mouseover', () => onHoverLink('highlight'))
110	            .on('mouseout', () => onHoverLink('downplay'));
111	
112	        const onHoverLink = (method?: 'highlight' | 'downplay') => {
113	            const visualMapModel = this.visualMapModel;
114	
115	            // TODO: TYPE More detailed action types
116	            visualMapModel.option.hoverLink && this.api.dispatchAction({
117	                type: method,
118	                batch: helper.makeHighDownBatch(
119	                    visualMapModel.findTargetDataIndices(pieceIndex),
120	                    visualMapModel
121	                )
122	            });
123	        };
124	    }
125	
126	    private _getItemAlign(): helper.ItemAlign {
127	        const visualMapModel = this.visualMapModel;
128	        const modelOption = visualMapModel.option;
129	
130	        if (modelOption.orient === 'vertical') {
131	            return helper.getItemAlign(
132	                visualMapModel, this.api, visualMapModel.itemSize
133	            );
134	        }
135	        else { // horizontal, most case left unless specifying right.
136	            let align = modelOption.align;
137	            if (!align || align === 'auto') {
138	                align = 'left';
139	            }
140	            return align;
141	        }
142	    }
143	
144	    private _renderEndsText(
145	        group: graphic.Group,
146	        text: string,
147	        itemSize: number[],
148	        showLabel: boolean,
149	        itemAlign: helper.ItemAlign
150	    ) {
151	        if (!text) {
152	            return;
153	        }
154	
155	        const itemGroup = new graphic.Group();
156	        const textStyleModel = this.visualMapModel.textStyleModel;
157	
158	        itemGroup.add(new graphic.Text({
159	            style: createTextStyle(textStyleModel, {
160	                x: showLabel ? (itemAlign === 'right' ? itemSize[0] : 0) : itemSize[0] / 2,
161	                y: itemSize[1] / 2,
162	                verticalAlign: 'middle',
163	                align: showLabel ? (itemAlign as TextAlign) : 'center',
164	                text
165	            })
166	        }));
167	
168	        group.add(itemGroup);
169	    }
170	
171	    /**
172	     * @private
173	     * @return {Object} {peiceList, endsText} The order is the same as screen pixel order.
174	     */
175	    private _getViewData() {
176	        const visualMapModel = this.visualMapModel;
177	
178	        const viewPieceList = zrUtil.map(visualMapModel.getPieceList(), function (piece, index) {
179	            return {piece: piece, indexInModelPieceList: index};
180	        });
181	        let endsText = visualMapModel.get('text');
182	
183	        // Consider orient and inverse.
184	        const orient = visualMapModel.get('orient');
185	        const inverse = visualMapModel.get('inverse');
186	
187	        // Order of model pieceList is always [low, ..., high]
188	        if (orient === 'horizontal' ? inverse : !inverse) {
189	            viewPieceList.reverse();
190	        }
191	        // Origin order of endsText is [high, low]
192	        else if (endsText) {
193	            endsText = endsText.slice().reverse();
194	        }
195	
196	        return {viewPieceList: viewPieceList, endsText: endsText};
197	    }
198	
199	    private _createItemSymbol(
200	        group: graphic.Group,
201	        representValue: number,
202	        shapeParam: number[]
203	    ) {
204	        group.add(createSymbol(
205	            // symbol will be string
206	            this.getControllerVisual(representValue, 'symbol') as string,
207	            shapeParam[0], shapeParam[1], shapeParam[2], shapeParam[3],
208	            // color will be string
209	            this.getControllerVisual(representValue, 'color') as string
210	        ));
211	    }
212	
213	    private _onItemClick(
214	        piece: VisualMappingOption['pieceList'][number]
215	    ) {
216	        const visualMapModel = this.visualMapModel;
217	        const option = visualMapModel.option;
218	        const selectedMode = option.selectedMode;
219	        if (!selectedMode) {
220	            return;
221	        }
222	        const selected = zrUtil.clone(option.selected);
223	        const newKey = visualMapModel.getSelectedMapKey(piece);
224	
225	        if (selectedMode === 'single' || selectedMode === true) {
226	            selected[newKey] = true;
227	            zrUtil.each(selected, function (o, key) {
228	                selected[key] = key === newKey;
229	            });
230	        }
231	        else {
232	            selected[newKey] = !selected[newKey];
233	        }
234	
235	        this.api.dispatchAction({
236	            type: 'selectDataRange',
237	            from: this.uid,
238	            visualMapId: this.visualMapModel.id,
239	            selected: selected
240	        });
241	    }
242	}
243	
244	export default PiecewiseVisualMapView;

