130	/**
131	 * Map from (baseAxis.dim + '_' + baseAxis.index) to min gap of two adjacent
132	 * values.
133	 * This works for time axes, value axes, and log axes.
134	 * For a single time axis, return value is in the form like
135	 * {'x_0': [1000000]}.
136	 * The value of 1000000 is in milliseconds.
137	 */
138	function getValueAxesMinGaps(barSeries: BarSeriesModel[]) {
139	    /**
140	     * Map from axis.index to values.
141	     * For a single time axis, axisValues is in the form like
142	     * {'x_0': [1495555200000, 1495641600000, 1495728000000]}.
143	     * Items in axisValues[x], e.g. 1495555200000, are time values of all
144	     * series.
145	     */
146	    const axisValues: Dictionary<number[]> = {};
147	    each(barSeries, function (seriesModel) {
148	        const cartesian = seriesModel.coordinateSystem as Cartesian2D;
149	        const baseAxis = cartesian.getBaseAxis();
150	        if (baseAxis.type !== 'time' && baseAxis.type !== 'value') {
151	            return;
152	        }
153	
154	        const data = seriesModel.getData();
155	        const key = baseAxis.dim + '_' + baseAxis.index;
156	        const dimIdx = data.getDimensionIndex(data.mapDimension(baseAxis.dim));
157	        const store = data.getStore();
158	        for (let i = 0, cnt = store.count(); i < cnt; ++i) {
159	            const value = store.get(dimIdx, i) as number;
160	            if (!axisValues[key]) {
161	                // No previous data for the axis
162	                axisValues[key] = [value];
163	            }
164	            else {
165	                // No value in previous series
166	                axisValues[key].push(value);
167	            }
168	            // Ignore duplicated time values in the same axis
169	        }
170	    });
171	
172	    const axisMinGaps: Dictionary<number> = {};
173	    for (const key in axisValues) {
174	        if (axisValues.hasOwnProperty(key)) {
175	            const valuesInAxis = axisValues[key];
176	            if (valuesInAxis) {
177	                // Sort axis values into ascending order to calculate gaps
178	                valuesInAxis.sort(function (a, b) {
179	                    return a - b;
180	                });
181	
182	                let min = null;
183	                for (let j = 1; j < valuesInAxis.length; ++j) {
184	                    const delta = valuesInAxis[j] - valuesInAxis[j - 1];
185	                    if (delta > 0) {
186	                        // Ignore 0 delta because they are of the same axis value
187	                        min = min === null ? delta : Math.min(min, delta);
188	                    }
189	                }
190	                // Set to null if only have one data
191	                axisMinGaps[key] = min;
192	            }
193	        }
194	    }
195	    return axisMinGaps;
196	}
