26	type Sampler = (frame: ArrayLike<number>) => number;
27	const samplers: Dictionary<Sampler> = {
28	    average: function (frame) {
29	        let sum = 0;
30	        let count = 0;
31	        for (let i = 0; i < frame.length; i++) {
32	            if (!isNaN(frame[i])) {
33	                sum += frame[i];
34	                count++;
35	            }
36	        }
37	        // Return NaN if count is 0
38	        return count === 0 ? NaN : sum / count;
39	    },
40	    sum: function (frame) {
41	        let sum = 0;
42	        for (let i = 0; i < frame.length; i++) {
43	            // Ignore NaN
44	            sum += frame[i] || 0;
45	        }
46	        return sum;
47	    },
48	    max: function (frame) {
49	        let max = -Infinity;
50	        for (let i = 0; i < frame.length; i++) {
51	            frame[i] > max && (max = frame[i]);
52	        }
53	        // NaN will cause illegal axis extent.
54	        return isFinite(max) ? max : NaN;
55	    },
56	    min: function (frame) {
57	        let min = Infinity;
58	        for (let i = 0; i < frame.length; i++) {
59	            frame[i] < min && (min = frame[i]);
60	        }
61	        // NaN will cause illegal axis extent.
62	        return isFinite(min) ? min : NaN;
63	    },
64	    minmax: function (frame) {
65	        let turningPointAbsoluteValue = -Infinity;
66	        let turningPointOriginalValue = -Infinity;
67	
68	        for (let i = 0; i < frame.length; i++) {
69	            const originalValue = frame[i];
70	            const absoluteValue = Math.abs(originalValue);
71	
72	            if (absoluteValue > turningPointAbsoluteValue) {
73	                turningPointAbsoluteValue = absoluteValue;
74	                turningPointOriginalValue = originalValue;
75	            }
76	        }
77	
78	        return isFinite(turningPointOriginalValue) ? turningPointOriginalValue : NaN;
79	    },
80	    // TODO
81	    // Median
82	    nearest: function (frame) {
83	        return frame[0];
84	    }
85	};
