161	
162	    _updateLabel(
163	        seriesModel: SunburstSeriesModel
164	    ) {
165	        const itemModel = this.node.getModel<SunburstSeriesNodeItemOption>();
166	        const normalLabelModel = itemModel.getModel('label');
167	
168	        const layout = this.node.getLayout();
169	        const angle = layout.endAngle - layout.startAngle;
170	
171	        const midAngle = (layout.startAngle + layout.endAngle) / 2;
172	        const dx = Math.cos(midAngle);
173	        const dy = Math.sin(midAngle);
174	
175	        const sector = this;
176	        const label = sector.getTextContent();
177	        const dataIndex = this.node.dataIndex;
178	        const labelMinAngle = normalLabelModel.get('minAngle') / 180 * Math.PI;
179	        const isNormalShown = normalLabelModel.get('show')
180	            && !(labelMinAngle != null && Math.abs(angle) < labelMinAngle);
181	        label.ignore = !isNormalShown;
182	
183	        // TODO use setLabelStyle
184	        zrUtil.each(DISPLAY_STATES, (stateName) => {
185	
186	            const labelStateModel = stateName === 'normal' ? itemModel.getModel('label')
187	                : itemModel.getModel([stateName, 'label']);
188	            const isNormal = stateName === 'normal';
189	
190	            const state = isNormal ? label : label.ensureState(stateName);
191	            let text = seriesModel.getFormattedLabel(dataIndex, stateName);
192	            if (isNormal) {
193	                text = text || this.node.name;
194	            }
195	
196	            state.style = createTextStyle(labelStateModel, {}, null, stateName !== 'normal', true);
197	            if (text) {
198	                state.style.text = text;
199	            }
200	            // Not displaying text when angle is too small
201	            const isShown = labelStateModel.get('show');
202	            if (isShown != null && !isNormal) {
203	                state.ignore = !isShown;
204	            }
205	
206	            const labelPosition = getLabelAttr(labelStateModel, 'position');
207	
208	            const sectorState = isNormal ? sector : sector.states[stateName];
209	            const labelColor = sectorState.style.fill as ColorString;
210	            sectorState.textConfig = {
211	                outsideFill: labelStateModel.get('color') === 'inherit' ? labelColor : null,
212	                inside: labelPosition !== 'outside'
213	            };
214	
215	            let r;
216	            const labelPadding = getLabelAttr(labelStateModel, 'distance') || 0;
217	            let textAlign = getLabelAttr(labelStateModel, 'align');
218	            const rotateType = getLabelAttr(labelStateModel, 'rotate');
219	            const flipStartAngle = Math.PI * 0.5;
220	            const flipEndAngle = Math.PI * 1.5;
221	            const midAngleNormal = normalizeRadian(rotateType === 'tangential' ? Math.PI / 2 - midAngle : midAngle);
222	
223	            // For text that is up-side down, rotate 180 degrees to make sure
224	            // it's readable
225	            const needsFlip = midAngleNormal > flipStartAngle
226	                && !isRadianAroundZero(midAngleNormal - flipStartAngle)
227	                && midAngleNormal < flipEndAngle;
228	
229	            if (labelPosition === 'outside') {
230	                r = layout.r + labelPadding;
231	                textAlign = needsFlip ? 'right' : 'left';
232	            }
233	            else {
234	                if (!textAlign || textAlign === 'center') {
235	                    // Put label in the center if it's a circle
236	                    if (angle === 2 * Math.PI && layout.r0 === 0) {
237	                        r = 0;
238	                    }
239	                    else {
240	                        r = (layout.r + layout.r0) / 2;
241	                    }
242	                    textAlign = 'center';
243	                }
244	                else if (textAlign === 'left') {
245	                    r = layout.r0 + labelPadding;
246	                    textAlign = needsFlip ? 'right' : 'left';
247	                }
248	                else if (textAlign === 'right') {
249	                    r = layout.r - labelPadding;
250	                    textAlign = needsFlip ? 'left' : 'right';
251	                }
252	            }
253	
254	            state.style.align = textAlign;
255	            state.style.verticalAlign = getLabelAttr(labelStateModel, 'verticalAlign') || 'middle';
256	
257	            state.x = r * dx + layout.cx;
258	            state.y = r * dy + layout.cy;
259	
260	            let rotate = 0;
261	            if (rotateType === 'radial') {
262	                rotate = normalizeRadian(-midAngle)
263	                    + (needsFlip ? Math.PI : 0);
264	            }
265	            else if (rotateType === 'tangential') {
266	                rotate = normalizeRadian(Math.PI / 2 - midAngle)
267	                    + (needsFlip ? Math.PI : 0);
268	            }
269	            else if (zrUtil.isNumber(rotateType)) {
270	                rotate = rotateType * Math.PI / 180;
271	            }
272	
273	            state.rotation = normalizeRadian(rotate);
274	        });
275	
276	
277	        type LabelOpt = SunburstSeriesOption['label'];
278	        function getLabelAttr<T extends keyof LabelOpt>(model: Model<LabelOpt>, name: T): LabelOpt[T] {
279	            const stateAttr = model.get(name);
280	            if (stateAttr == null) {
281	                return normalLabelModel.get(name) as LabelOpt[T];
282	            }
283	            return stateAttr;
284	        }
285	
286	        label.dirtyStyle();
287	    }
288	}
