import SeriesData from '../src/data/SeriesData';

describe('seriesdata-rawindexof-npe', function () {
    it('rawIndexOf should not throw when dimension has no inverted index', function () {
        const data = new SeriesData(null, null);
        (data as any)._store = {
            initData: function () {},
            count: function () { return 0; }
        };
        data.initData([]);
        // '_invertedIndicesMap' is empty here, so the dim has no inverted index.
        expect(function () {
            // eslint-disable-next-line dot-notation
            expect(data.rawIndexOf('nonexistent_dim' as any, 0 as any)).toBe(-1);
        }).not.toThrow();
    });
});

