650	        // In which case, the data is not main data in series.
651	        const seriesIndex = ecData.seriesIndex;
652	        const seriesModel = ecModel.getSeriesByIndex(seriesIndex);
653	
654	        // For example, graph link.
655	        const dataModel = ecData.dataModel || seriesModel;
