705	                tooltipModel, markupText, params, asyncTicket,
706	                e.offsetX, e.offsetY, e.position, e.target,
707	                markupStyleCreator
708	            );
709	        });
710	
711	        // FIXME
712	        // duplicated showtip if manuallyShowTip is called from dispatchAction.
713	        dispatchAction({
