1194	        return;
1195	    }
1196	
1197	    const queryResult = queryReferringComponents(
1198	        ecModel,
1199	        componentMainType,
1200	        queryOptionMap.get(componentMainType),
1201	        { useDefault: false, enableAll: false, enableNone: false }
1202	    );
1203	    const model = queryResult.models[0];
1204	    if (!model) {
1205	        return;
1206	    }
1207	
1208	    const view = api.getViewOfComponentModel(model);
1209	    let el: ECElement;
1210	    view.group.traverse((subEl: ECElement) => {
1211	        const tooltipConfig = getECData(subEl).tooltipConfig;
1212	        if (tooltipConfig && tooltipConfig.name === payload.name) {
1213	            el = subEl;
1214	            return true; // stop
1215	        }
1216	    });
1217	
1218	    if (el) {
1219	        return {
1220	            componentMainType,
1221	            componentIndex: model.componentIndex,
1222	            el
1223	        };
1224	    }
