328	        // Using pathRect brings convenience to users sacle svg path.
329	        const pathRect = (shape.width != null && shape.height != null)
330	            ? {
331	                x: shape.x || 0,
332	                y: shape.y || 0,
333	                width: shape.width,
334	                height: shape.height
335	            } as RectLike
336	            : null;
337	        const pathData = getPathData(shape);
338	        // Path is also used for icon, so layout 'center' by default.
339	        el = graphicUtil.makePath(pathData, null, pathRect, shape.layout || 'center');
340	        customInnerStore(el).customPathData = pathData;
341	    }
342	    else if (graphicType === 'image') {
343	        el = new graphicUtil.Image({});
344	        customInnerStore(el).customImagePath = (elOption as CustomImageOption).style.image;
