import { init } from '../../src/echarts.all';
import { createChart, removeChart } from '../test/ut/core/utHelper';

describe('aria SSR safety', function () {
    it('does not throw when aria is enabled in SSR mode (no dom)', function () {
        const chart = init(null, null, {
            renderer: 'svg',
            ssr: true,
            width: 500,
            height: 400
        });
        expect(function () {
            chart.setOption({
                aria: {
                    enabled: true
                },
                xAxis: { type: 'category', data: ['a', 'b'] },
                yAxis: {},
                series: [{ type: 'bar', data: [1, 2] }]
            });
            chart.renderToSVGString();
        }).not.toThrow();
        chart.dispose();
    });

    it('still sets aria-label on the dom in browser mode', function () {
        const chart = createChart();
        chart.setOption({
            aria: {
                enabled: true
            },
            xAxis: { type: 'category', data: ['a', 'b'] },
            yAxis: {},
            series: [{ type: 'bar', data: [1, 2] }]
        });
        expect(chart.getDom().getAttribute('aria-label')).toBeTruthy();
        removeChart(chart);
    });
});

