import { createChart } from '../test/ut/core/utHelper';

describe('sankey-undefined-options', function () {

    it('does not throw when links / nodes / levels are undefined', function () {
        const chart = createChart();
        expect(function () {
            chart.setOption({
                series: [{
                    type: 'sankey',
                    data: [
                        {name: 'a'},
                        {name: 'b'}
                    ]
                    // links and levels are undefined
                }]
            });
        }).not.toThrow();

        expect(function () {
            chart.setOption({
                series: [{
                    type: 'sankey',
                    // nodes/data and levels are undefined
                    links: [
                        {source: 'a', target: 'b', value: 5}
                    ]
                }]
            });
        }).not.toThrow();

        expect(function () {
            chart.setOption({
                series: [{
                    type: 'sankey',
                    data: [
                        {name: 'a'},
                        {name: 'b'}
                    ],
                    links: [
                        {source: 'a', target: 'b', value: 5}
                    ],
                    levels: undefined
                }]
            });
        }).not.toThrow();

        chart.dispose();
    });

    it('still builds the graph normally when links / nodes / levels are provided', function () {
        const chart = createChart();
        chart.setOption({
            series: [{
                type: 'sankey',
                data: [
                    {name: 'a'},
                    {name: 'b'}
                ],
                links: [
                    {source: 'a', target: 'b', value: 5}
                ],
                levels: [
                    {depth: 0},
                    {depth: 1}
                ]
            }]
        });
        const series = (chart as any).getModel().getSeriesByIndex(0);
        expect(series.getData().count()).toBe(2);
        expect(series.getGraph().edgeCount()).toBe(1);
        chart.dispose();
    });
});

