    it('debug', function () {
        const chart = createChart();
        chart.setOption({
            xAxis: { data: ['a', 'b', 'c'] },
            yAxis: {},
            series: [{
                type: 'candlestick',
                data: [
                    [20, 34, 10, 38],
                    [40, 35, 30, 50],
                    [31, 38, 28, 44]
                ]
            }]
        });
        const seriesModel = chart.getModel().getSeriesByIndex(0) as any;
        const data = seriesModel.getData();
        console.log('count', data.count(), 'isLarge', seriesModel.pipelineContext && seriesModel.pipelineContext.large);
        const el0 = data.getItemGraphicEl(0) as any;
        console.log('el0', !!el0, el0 && el0.type, el0 && isHighDownDispatcher(el0));
        console.log('states', el0 && Object.keys(el0.states || {}));
        removeChart(chart);
    });
});

