    it('dump ignored labels', function () {
        const chart = createChart({ width: 600, height: 400 });
        const opt = require('./pie-label-visibility-debug-option.cjs');
        chart.setOption(opt);
        chart.getZr().refreshImmediately();
        const data = chart.getModel().getSeriesByIndex(1).getData();
        const out: any[] = [];
        data.each(function (idx: number) {
            const sector = data.getItemGraphicEl(idx) as any;
            const label = sector.getTextContent();
            out.push({ name: data.getName(idx), ignore: !!label.ignore, x: label.x, y: label.y });
        });
        console.log(JSON.stringify(out, null, 1));
        removeChart(chart);
    });
});

