313	    const valueAxis = opt.coordSys.getOtherAxis(opt.coordSys.getBaseAxis());
314	    const zeroPx = valueAxis.toGlobalCoord(valueAxis.dataToCoord(0));
315	    const pxSignIdx = 1 - +(layout[valueDim.wh] <= 0);
316	    let boundingLength;
317	
318	    if (zrUtil.isArray(symbolBoundingData)) {
319	        const symbolBoundingExtent = [
320	            convertToCoordOnAxis(valueAxis, symbolBoundingData[0]) - zeroPx,
321	            convertToCoordOnAxis(valueAxis, symbolBoundingData[1]) - zeroPx
322	        ];
323	        symbolBoundingExtent[1] < symbolBoundingExtent[0] && (symbolBoundingExtent.reverse());
324	        boundingLength = symbolBoundingExtent[pxSignIdx];
325	    }
326	    else if (symbolBoundingData != null) {
327	        boundingLength = convertToCoordOnAxis(valueAxis, symbolBoundingData) - zeroPx;
328	    }
329	    else if (symbolRepeat) {
330	        boundingLength = opt.coordSysExtent[valueDim.index][pxSignIdx] - zeroPx;
331	    }
