269	    incrementalRender(
270	        params: StageHandlerProgressParams,
271	        customSeries: CustomSeriesModel,
272	        ecModel: GlobalModel,
273	        api: ExtensionAPI,
274	        payload: Payload
275	    ): void {
276	        const data = customSeries.getData();
277	        const renderItem = makeRenderItem(customSeries, data, ecModel, api);
278	        const progressiveEls: Element[] = this._progressiveEls = [];
279	
280	        function setIncrementalAndHoverLayer(el: Displayable) {
281	            if (!el.isGroup) {
282	                el.incremental = true;
283	                el.ensureState('emphasis').hoverLayer = true;
284	            }
285	        }
286	        for (let idx = params.start; idx < params.end; idx++) {
287	            const el = createOrUpdateItem(
288	                null, null, idx, renderItem(idx, payload), customSeries, this.group, data
289	            );
290	            if (el) {
291	                el.traverse(setIncrementalAndHoverLayer);
292	                progressiveEls.push(el);
293	            }
294	        }
295	    }
