301	    filterForExposedEvent(
302	        eventType: string, query: EventQueryItem, targetEl: Element, packedEvent: ECActionEvent
303	    ): boolean {
304	        const elementName = query.element;
305	        if (elementName == null || targetEl.name === elementName) {
306	            return true;
307	        }
308	
309	        // Enable to give a name on a group made by `renderItem`, and listen
310	        // events that are triggered by its descendents.
311	        while ((targetEl = (targetEl.__hostTarget || targetEl.parent)) && targetEl !== this.group) {
312	            if (targetEl.name === elementName) {
313	                return true;
314	            }
315	        }
316	
317	        return false;
318	    }
319	}
