575	function updateZ(
576	    el: Element,
577	    elOption: CustomElementOption,
578	    seriesModel: CustomSeriesModel
579	): void {
580	    // Group not support textContent and not support z yet.
581	    if (el.isGroup) {
582	        return;
583	    }
584	
585	    const elDisplayable = el as Displayable;
586	    const currentZ = seriesModel.currentZ;
587	    const currentZLevel = seriesModel.currentZLevel;
588	    // Always erase.
589	    elDisplayable.z = currentZ;
590	    elDisplayable.zlevel = currentZLevel;
591	    // z2 must not be null/undefined, otherwise sort error may occur.
592	    const optZ2 = (elOption as CustomDisplayableOption).z2;
593	    optZ2 != null && (elDisplayable.z2 = optZ2 || 0);
594	
595	    for (let i = 0; i < STATES.length; i++) {
596	        updateZForEachState(elDisplayable, elOption, STATES[i]);
