600	function updateZForEachState(
601	    elDisplayable: Displayable,
602	    elOption: CustomDisplayableOption,
603	    state: DisplayState
604	): void {
605	    const isNormal = state === NORMAL;
606	    const elStateOpt = isNormal ? elOption : retrieveStateOption(
607	        elOption as CustomElementOption,
608	        state as DisplayStateNonNormal
609	    );
610	    const optZ2 = elStateOpt ? elStateOpt.z2 : null;
611	    let stateObj;
612	    if (optZ2 != null) {
613	        // Do not `ensureState` until required.
614	        stateObj = isNormal ? elDisplayable : elDisplayable.ensureState(state);
615	        stateObj.z2 = optZ2 || 0;
616	    }
617	}
