619	function makeRenderItem(
620	    customSeries: CustomSeriesModel,
621	    data: SeriesData<CustomSeriesModel>,
622	    ecModel: GlobalModel,
623	    api: ExtensionAPI
624	) {
625	    const renderItem = customSeries.get('renderItem');
626	    const coordSys = customSeries.coordinateSystem;
627	    let prepareResult = {} as ReturnType<PrepareCustomInfo>;
628	
629	    if (coordSys) {
630	        if (__DEV__) {
631	            assert(renderItem, 'series.render is required.');
632	            assert(
633	                coordSys.prepareCustoms || prepareCustoms[coordSys.type],
634	                'This coordSys does not support custom series.'
635	            );
636	        }
637	
638	        // `coordSys.prepareCustoms` is used for external coord sys like bmap.
639	        prepareResult = coordSys.prepareCustoms
640	            ? coordSys.prepareCustoms(coordSys)
641	            : prepareCustoms[coordSys.type](coordSys);
642	    }
643	
644	    const userAPI = defaults({
645	        getWidth: api.getWidth,
646	        getHeight: api.getHeight,
647	        getZr: api.getZr,
648	        getDevicePixelRatio: api.getDevicePixelRatio,
649	        value: value,
650	        style: style,
651	        ordinalRawValue: ordinalRawValue,
652	        styleEmphasis: styleEmphasis,
653	        visual: visual,
654	        barLayout: barLayout,
655	        currentSeriesIndices: currentSeriesIndices,
656	        font: font
657	    }, prepareResult.api || {}) as CustomSeriesRenderItemAPI;
658	
659	    const userParams: CustomSeriesRenderItemParams = {
660	        // The life cycle of context: current round of rendering.
661	        // The global life cycle is probably not necessary, because
662	        // user can store global status by themselves.
663	        context: {},
664	        seriesId: customSeries.id,
665	        seriesName: customSeries.name,
666	        seriesIndex: customSeries.seriesIndex,
667	        coordSys: prepareResult.coordSys,
668	        dataInsideLength: data.count(),
669	        encode: wrapEncodeDef(customSeries.getData())
670	    } as CustomSeriesRenderItemParams;
671	
672	    // If someday intending to refactor them to a class, should consider do not
673	    // break change: currently these attribute member are encapsulated in a closure
674	    // so that do not need to force user to call these method with a scope.
675	
676	    // Do not support call `api` asynchronously without dataIndexInside input.
677	    let currDataIndexInside: number;
678	    let currItemModel: Model<CustomSeriesOption>;
679	    let currItemStyleModels: Partial<Record<DisplayState, Model<CustomSeriesOption['itemStyle']>>> = {};
680	    let currLabelModels: Partial<Record<DisplayState, Model<CustomSeriesOption['label']>>> = {};
681	
682	    const seriesItemStyleModels = {} as Record<DisplayState, Model<CustomSeriesOption['itemStyle']>>;
683	
684	    const seriesLabelModels = {} as Record<DisplayState, Model<CustomSeriesOption['label']>>;
685	
686	    for (let i = 0; i < STATES.length; i++) {
687	        const stateName = STATES[i];
688	        seriesItemStyleModels[stateName] = (customSeries as Model<CustomSeriesOption>)
689	            .getModel(PATH_ITEM_STYLE[stateName]);
690	        seriesLabelModels[stateName] = (customSeries as Model<CustomSeriesOption>)
691	            .getModel(PATH_LABEL[stateName]);
692	    }
693	
694	    function getItemModel(dataIndexInside: number): Model<CustomSeriesOption> {
695	        return dataIndexInside === currDataIndexInside
696	            ? (currItemModel || (currItemModel = data.getItemModel(dataIndexInside)))
697	            : data.getItemModel(dataIndexInside);
698	    }
699	    function getItemStyleModel(dataIndexInside: number, state: DisplayState) {
700	        return !data.hasItemOption
701	            ? seriesItemStyleModels[state]
702	            : dataIndexInside === currDataIndexInside
703	            ? (currItemStyleModels[state] || (
704	                currItemStyleModels[state] = getItemModel(dataIndexInside).getModel(PATH_ITEM_STYLE[state])
705	            ))
706	            : getItemModel(dataIndexInside).getModel(PATH_ITEM_STYLE[state]);
707	    }
708	    function getLabelModel(dataIndexInside: number, state: DisplayState) {
709	        return !data.hasItemOption
710	            ? seriesLabelModels[state]
711	            : dataIndexInside === currDataIndexInside
712	            ? (currLabelModels[state] || (
713	                currLabelModels[state] = getItemModel(dataIndexInside).getModel(PATH_LABEL[state])
714	            ))
715	            : getItemModel(dataIndexInside).getModel(PATH_LABEL[state]);
716	    }
717	
718	    return function (dataIndexInside: number, payload: Payload): CustomElementOption {
719	        currDataIndexInside = dataIndexInside;
720	        currItemModel = null;
721	        currItemStyleModels = {};
722	        currLabelModels = {};
723	
724	        return renderItem && renderItem(
725	            defaults({
726	                dataIndexInside: dataIndexInside,
727	                dataIndex: data.getRawIndex(dataIndexInside),
728	                // Can be used for optimization when zoom or roam.
729	                actionType: payload ? payload.type : null
730	            } as CustomSeriesRenderItemParams, userParams),
731	            userAPI
732	        );
733	    };
