735	    /**
736	     * @public
737	     * @param dim by default 0.
738	     * @param dataIndexInside by default `currDataIndexInside`.
739	     */
740	    function value(dim?: DimensionLoose, dataIndexInside?: number): ParsedValue {
741	        dataIndexInside == null && (dataIndexInside = currDataIndexInside);
742	        return data.getStore().get(data.getDimensionIndex(dim || 0), dataIndexInside);
