747	     * @param dim by default 0.
748	     * @param dataIndexInside by default `currDataIndexInside`.
749	     */
750	    function ordinalRawValue(dim?: DimensionLoose, dataIndexInside?: number): ParsedValue | OrdinalRawValue {
751	        dataIndexInside == null && (dataIndexInside = currDataIndexInside);
752	        dim = dim || 0;
753	        const dimInfo = data.getDimensionInfo(dim);
754	        if (!dimInfo) {
755	            const dimIndex = data.getDimensionIndex(dim);
756	            return dimIndex >= 0 ? data.getStore().get(dimIndex, dataIndexInside) : undefined;
757	        }
758	        const val = data.get(dimInfo.name, dataIndexInside);
