806	            ? retrieve2(
807	                customSeries.getFormattedLabel(dataIndexInside, NORMAL),
808	                getDefaultLabel(data, dataIndexInside)
809	            )
810	            : null;
811	        const textConfig = labelStyleHelper.createTextConfig(labelModel, opt, false);
812	
813	        preFetchFromExtra(userProps, itemStyle);
814	        itemStyle = convertToEC4StyleForCustomSerise(itemStyle, textStyle, textConfig);
815	
816	        userProps && applyUserPropsAfter(itemStyle, userProps);
817	        (itemStyle as LegacyStyleProps).legacy = true;
818	
819	        return itemStyle;
