251	/**
252	 * Calculate interval for category axis ticks and labels.
253	 * To get precise result, at least one of `getRotate` and `isHorizontal`
254	 * should be implemented in axis.
255	 */
256	export function calculateCategoryInterval(axis: Axis) {
257	    const params = fetchAutoCategoryIntervalCalculationParams(axis);
258	    const labelFormatter = makeLabelFormatter(axis);
259	    const rotation = (params.axisRotate - params.labelRotate) / 180 * Math.PI;
260	
261	    const ordinalScale = axis.scale as OrdinalScale;
262	    const ordinalExtent = ordinalScale.getExtent();
263	    // Providing this method is for optimization:
264	    // avoid generating a long array by `getTicks`
265	    // in large category data case.
266	    const tickCount = ordinalScale.count();
267	
268	    if (ordinalExtent[1] - ordinalExtent[0] < 1) {
269	        return 0;
270	    }
271	
272	    let step = 1;
273	    // Simple optimization. Empirical value: tick count should less than 40.
274	    if (tickCount > 40) {
275	        step = Math.max(1, Math.floor(tickCount / 40));
276	    }
277	    let tickValue = ordinalExtent[0];
278	    const unitSpan = axis.dataToCoord(tickValue + 1) - axis.dataToCoord(tickValue);
279	    const unitW = Math.abs(unitSpan * Math.cos(rotation));
280	    const unitH = Math.abs(unitSpan * Math.sin(rotation));
281	
282	    let maxW = 0;
283	    let maxH = 0;
284	
285	    // Caution: Performance sensitive for large category data.
286	    // Consider dataZoom, we should make appropriate step to avoid O(n) loop.
287	    for (; tickValue <= ordinalExtent[1]; tickValue += step) {
288	        let width = 0;
289	        let height = 0;
290	
291	        // Not precise, do not consider align and vertical align
292	        // and each distance from axis line yet.
293	        const rect = textContain.getBoundingRect(
294	            labelFormatter({ value: tickValue }), params.font, 'center', 'top'
295	        );
296	        // Magic number
297	        width = rect.width * 1.3;
298	        height = rect.height * 1.3;
299	
300	        // Min size, void long loop.
301	        maxW = Math.max(maxW, width, 7);
302	        maxH = Math.max(maxH, height, 7);
303	    }
304	
305	    let dw = maxW / unitW;
306	    let dh = maxH / unitH;
307	    // 0/0 is NaN, 1/0 is Infinity.
308	    isNaN(dw) && (dw = Infinity);
309	    isNaN(dh) && (dh = Infinity);
310	    let interval = Math.max(0, Math.floor(Math.min(dw, dh)));
311	
312	    const cache = inner(axis.model);
313	    const axisExtent = axis.getExtent();
314	    const lastAutoInterval = cache.lastAutoInterval;
315	    const lastTickCount = cache.lastTickCount;
316	
317	    // Use cache to keep interval stable while moving zoom window,
318	    // otherwise the calculated interval might jitter when the zoom
319	    // window size is close to the interval-changing size.
320	    // For example, if all of the axis labels are `a, b, c, d, e, f, g`.
321	    // The jitter will cause that sometimes the displayed labels are
322	    // `a, d, g` (interval: 2) sometimes `a, c, e`(interval: 1).
323	    if (lastAutoInterval != null
324	        && lastTickCount != null
325	        && Math.abs(lastAutoInterval - interval) <= 1
326	        && Math.abs(lastTickCount - tickCount) <= 1
327	        // Always choose the bigger one, otherwise the critical
328	        // point is not the same when zooming in or zooming out.
329	        && lastAutoInterval > interval
330	        // If the axis change is caused by chart resize, the cache should not
331	        // be used. Otherwise some hidden labels might not be shown again.
332	        && cache.axisExtent0 === axisExtent[0]
333	        && cache.axisExtent1 === axisExtent[1]
334	    ) {
335	        interval = lastAutoInterval;
336	    }
337	    // Only update cache if cache not used, otherwise the
338	    // changing of interval is too insensitive.
339	    else {
340	        cache.lastTickCount = tickCount;
341	        cache.lastAutoInterval = interval;
342	        cache.axisExtent0 = axisExtent[0];
343	        cache.axisExtent1 = axisExtent[1];
344	    }
345	
346	    return interval;
347	}
348	
349	function fetchAutoCategoryIntervalCalculationParams(axis: Axis) {
350	    const labelModel = axis.getLabelModel();
351	    return {
352	        axisRotate: axis.getRotate
353	            ? axis.getRotate()
354	            : ((axis as Axis2D).isHorizontal && !(axis as Axis2D).isHorizontal())
355	            ? 90
356	            : 0,
357	        labelRotate: labelModel.get('rotate') || 0,
358	        font: labelModel.getFont()
359	    };
360	}
