362	interface MakeLabelsResultObj {
363	    formattedLabel: string
364	    rawLabel: string
365	    tickValue: number
366	}
367	
368	function makeLabelsByNumericCategoryInterval(axis: Axis, categoryInterval: number): MakeLabelsResultObj[];
369	/* eslint-disable-next-line */
370	function makeLabelsByNumericCategoryInterval(axis: Axis, categoryInterval: number, onlyTick: false): MakeLabelsResultObj[];
371	function makeLabelsByNumericCategoryInterval(axis: Axis, categoryInterval: number, onlyTick: true): number[];
372	function makeLabelsByNumericCategoryInterval(axis: Axis, categoryInterval: number, onlyTick?: boolean) {
373	    const labelFormatter = makeLabelFormatter(axis);
374	    const ordinalScale = axis.scale as OrdinalScale;
375	    const ordinalExtent = ordinalScale.getExtent();
376	    const labelModel = axis.getLabelModel();
377	    const result: (MakeLabelsResultObj | number)[] = [];
378	
379	    // TODO: axisType: ordinalTime, pick the tick from each month/day/year/...
380	
381	    const step = Math.max((categoryInterval || 0) + 1, 1);
382	    let startTick = ordinalExtent[0];
383	    const tickCount = ordinalScale.count();
384	
385	    // Calculate start tick based on zero if possible to keep label consistent
386	    // while zooming and moving while interval > 0. Otherwise the selection
387	    // of displayable ticks and symbols probably keep changing.
388	    // 3 is empirical value.
389	    if (startTick !== 0 && step > 1 && tickCount / step > 2) {
390	        startTick = Math.round(Math.ceil(startTick / step) * step);
391	    }
392	
393	    // (1) Only add min max label here but leave overlap checking
394	    // to render stage, which also ensure the returned list
395	    // suitable for splitLine and splitArea rendering.
396	    // (2) Scales except category always contain min max label so
397	    // do not need to perform this process.
398	    const showAllLabel = shouldShowAllLabels(axis);
399	    const includeMinLabel = labelModel.get('showMinLabel') || showAllLabel;
400	    const includeMaxLabel = labelModel.get('showMaxLabel') || showAllLabel;
401	
402	    if (includeMinLabel && startTick !== ordinalExtent[0]) {
403	        addItem(ordinalExtent[0]);
404	    }
405	
406	    // Optimize: avoid generating large array by `ordinalScale.getTicks()`.
407	    let tickValue = startTick;
408	    for (; tickValue <= ordinalExtent[1]; tickValue += step) {
409	        addItem(tickValue);
410	    }
411	
412	    if (includeMaxLabel && tickValue - step !== ordinalExtent[1]) {
413	        addItem(ordinalExtent[1]);
414	    }
415	
416	    function addItem(tickValue: number) {
417	        const tickObj = { value: tickValue };
418	        result.push(onlyTick
419	            ? tickValue
420	            : {
421	                formattedLabel: labelFormatter(tickObj),
422	                rawLabel: ordinalScale.getLabel(tickObj),
423	                tickValue: tickValue
424	            }
425	        );
426	    }
427	
428	    return result;
429	}
430	
431	type CategoryIntervalCb = (tickVal: number, rawLabel: string) => boolean;
432	
433	// When interval is function, the result `false` means ignore the tick.
434	// It is time consuming for large category data.
435	/* eslint-disable-next-line */
436	function makeLabelsByCustomizedCategoryInterval(axis: Axis, categoryInterval: CategoryIntervalCb): MakeLabelsResultObj[];
437	/* eslint-disable-next-line */
438	function makeLabelsByCustomizedCategoryInterval(axis: Axis, categoryInterval: CategoryIntervalCb, onlyTick: false): MakeLabelsResultObj[];
439	/* eslint-disable-next-line */
440	function makeLabelsByCustomizedCategoryInterval(axis: Axis, categoryInterval: CategoryIntervalCb, onlyTick: true): number[];
441	function makeLabelsByCustomizedCategoryInterval(axis: Axis, categoryInterval: CategoryIntervalCb, onlyTick?: boolean) {
442	    const ordinalScale = axis.scale;
443	    const labelFormatter = makeLabelFormatter(axis);
444	    const result: (MakeLabelsResultObj | number)[] = [];
445	
446	    zrUtil.each(ordinalScale.getTicks(), function (tick) {
447	        const rawLabel = ordinalScale.getLabel(tick);
448	        const tickValue = tick.value;
449	        if (categoryInterval(tick.value, rawLabel)) {
450	            result.push(
451	                onlyTick
452	                ? tickValue
453	                : {
454	                    formattedLabel: labelFormatter(tick),
455	                    rawLabel: rawLabel,
456	                    tickValue: tickValue
457	                }
458	            );
459	        }
460	    });
461	
462	    return result;
463	}

    });
    makeAction('unSelect', {
