33	type Datas = { [key in SeriesDataType]?: SeriesData };
34	type StructReferDataAttr = 'data' | 'edgeData';
35	type StructAttr = 'tree' | 'graph';
36	
37	const inner = makeInner<{
38	    datas: Datas;
39	    mainData: SeriesData;
40	}, SeriesData>();
41	
42	
43	// Caution:
44	// In most case, either seriesData or its shallow clones (see seriesData.cloneShallow)
45	// is active in echarts process. So considering heap memory consumption,
46	// we do not clone tree or graph, but share them among seriesData and its shallow clones.
47	// But in some rare case, we have to keep old seriesData (like do animation in chart). So
48	// please take care that both the old seriesData and the new seriesData share the same tree/graph.
49	
50	type LinkSeriesDataOpt = {
51	    mainData: SeriesData;
52	    // For example, instance of Graph or Tree.
53	    struct: {
54	        update: () => void;
55	    } & {
56	        [key in StructReferDataAttr]?: SeriesData
57	    };
58	    // Will designate: `mainData[structAttr] = struct;`
59	    structAttr: StructAttr;
60	    datas?: Datas;
61	    // { dataType: attr },
62	    // Will designate: `struct[datasAttr[dataType]] = list;`
63	    datasAttr?: { [key in SeriesDataType]?: StructReferDataAttr };
64	};
65	
66	function linkSeriesData(opt: LinkSeriesDataOpt): void {
67	    const mainData = opt.mainData;
68	    let datas = opt.datas;
69	
70	    if (!datas) {
71	        datas = { main: mainData };
72	        opt.datasAttr = { main: 'data' };
73	    }
74	    opt.datas = opt.mainData = null;
75	
76	    linkAll(mainData, datas, opt);
77	
78	    // Porxy data original methods.
79	    each(datas, function (data: SeriesData) {
80	        each(mainData.TRANSFERABLE_METHODS, function (methodName) {
81	            data.wrapMethod(methodName, curry(transferInjection, opt));
82	        });
83	    });
84	
85	    // Beyond transfer, additional features should be added to `cloneShallow`.
86	    mainData.wrapMethod('cloneShallow', curry(cloneShallowInjection, opt));
87	
88	    // Only mainData trigger change, because struct.update may trigger
89	    // another changable methods, which may bring about dead lock.
90	    each(mainData.CHANGABLE_METHODS, function (methodName) {
91	        mainData.wrapMethod(methodName, curry(changeInjection, opt));
92	    });
93	
94	    // Make sure datas contains mainData.
95	    assert(datas[mainData.dataType] === mainData);
96	}
97	
98	function transferInjection(this: SeriesData, opt: LinkSeriesDataOpt, res: SeriesData): unknown {
99	    if (isMainData(this)) {
100	        // Transfer datas to new main data.
101	        const datas = extend({}, inner(this).datas);
102	        datas[this.dataType] = res;
103	        linkAll(res, datas, opt);
104	    }
105	    else {
106	        // Modify the reference in main data to point newData.
107	        linkSingle(res, this.dataType, inner(this).mainData, opt);
108	    }
109	    return res;
110	}
111	
112	function changeInjection(opt: LinkSeriesDataOpt, res: unknown): unknown {
113	    opt.struct && opt.struct.update();
114	    return res;
115	}
116	
117	function cloneShallowInjection(opt: LinkSeriesDataOpt, res: SeriesData): SeriesData {
118	    // cloneShallow, which brings about some fragilities, may be inappropriate
119	    // to be exposed as an API. So for implementation simplicity we can make
120	    // the restriction that cloneShallow of not-mainData should not be invoked
121	    // outside, but only be invoked here.
122	    each(inner(res).datas, function (data: SeriesData, dataType) {
123	        data !== res && linkSingle(data.cloneShallow(), dataType, res, opt);
124	    });
125	    return res;
126	}
127	
128	/**
129	 * Supplement method to List.
130	 *
131	 * @public
132	 * @param [dataType] If not specified, return mainData.
133	 */
134	function getLinkedData(this: SeriesData, dataType?: SeriesDataType): SeriesData {
135	    const mainData = inner(this).mainData;
136	    return (dataType == null || mainData == null)
137	        ? mainData
138	        : inner(mainData).datas[dataType];
139	}
140	
141	/**
142	 * Get list of all linked data
143	 */
144	function getLinkedDataAll(this: SeriesData): {
145	    data: SeriesData,
146	    type?: SeriesDataType
147	}[] {
148	    const mainData = inner(this).mainData;
149	    return (mainData == null)
150	        ? [{ data: mainData }]
151	        : map(keys(inner(mainData).datas), function (type) {
152	            return {
153	                type,
154	                data: inner(mainData).datas[type]
155	            };
156	        });
157	}
158	
159	function isMainData(data: SeriesData): boolean {
160	    return inner(data).mainData === data;
161	}
162	
163	function linkAll(mainData: SeriesData, datas: Datas, opt: LinkSeriesDataOpt): void {
164	    inner(mainData).datas = {};
165	    each(datas, function (data: SeriesData, dataType) {
166	        linkSingle(data, dataType, mainData, opt);
167	    });
168	}
169	
170	function linkSingle(data: SeriesData, dataType: SeriesDataType, mainData: SeriesData, opt: LinkSeriesDataOpt): void {
171	    inner(mainData).datas[dataType] = data;
172	    inner(data).mainData = mainData;
173	
174	    data.dataType = dataType;
175	
176	    if (opt.struct) {
177	        data[opt.structAttr] = opt.struct as any;
178	        opt.struct[opt.datasAttr[dataType]] = data;
179	    }
180	
181	    // Supplement method.
182	    data.getLinkedData = getLinkedData;
183	    data.getLinkedDataAll = getLinkedDataAll;
184	}
185	
186	export default linkSeriesData;

